export const SUITS_CRM_HTML: string = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Suits in Social Media CRM</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\"><link href=\"https://fonts.googleapis.com/css2?family=League+Spartan:wght@400;500;600;700;800;900&display=swap\" rel=\"stylesheet\">\n<style>\n  :root { color-scheme: light; --acc: #b05cff; --acc-dark: #7a2fd1; --acc-soft: #efe0ff; --ink: #000; --line: #e4e4e4; --grey: #6b6b6b; }\n  * { box-sizing: border-box; }\n  body { margin: 0; font-family: 'League Spartan', 'Poppins', -apple-system, 'Segoe UI', Arial, sans-serif; background: #fff; color: var(--ink); }\n  .app { max-width: 1180px; margin: 0 auto; padding: 24px 24px 60px; }\n  .brand { display: flex; align-items: center; gap: 16px; }\n  .brand img { height: 64px; width: auto; display: block; background: #000; border-radius: 12px; padding: 6px 8px; }\n  h1 { font-size: 44px; line-height: 1; margin: 0; font-weight: 900; letter-spacing: -0.01em; }\n  .subtitle { color: var(--grey); font-size: 15px; margin: 6px 0 0; font-weight: 500; }\n  .divider { height: 6px; background: var(--acc); border-radius: 3px; margin: 18px 0 20px; }\n  nav.tabs { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 22px; border-bottom: 2px solid var(--ink); padding-bottom: 12px; }\n  nav.tabs button { background: #fff; color: var(--ink); border: 2px solid var(--ink); padding: 9px 16px; border-radius: 10px; font-family: inherit; font-size: 14px; font-weight: 800; cursor: pointer; }\n  nav.tabs button:hover { background: var(--acc-soft); border-color: var(--acc-dark); }\n  nav.tabs button.active { background: var(--ink); color: var(--acc); border-color: var(--ink); }\n  .tab-section { display: none; }\n  .tab-section.active { display: block; }\n  .card { background: #fff; border: 2px solid var(--ink); border-radius: 14px; padding: 20px 22px; margin-bottom: 20px; }\n  .card h2 { font-size: 22px; margin: 0 0 4px; font-weight: 900; }\n  .card h3 { font-size: 16px; margin: 18px 0 8px; font-weight: 900; }\n  .card .hint { font-size: 14px; color: var(--grey); margin: 0 0 14px; font-weight: 500; }\n  .goal-card { background: var(--ink); color: #fff; }\n  .goal-card h2 { color: var(--acc); }\n  .goal-top { display: flex; justify-content: space-between; align-items: baseline; flex-wrap: wrap; gap: 8px; }\n  .goal-amount { font-size: 42px; font-weight: 900; color: var(--acc); }\n  .goal-sub { margin-top: 8px; font-size: 13px; color: #fff; }\n  .progress-outer { background: #2a2a2a; border-radius: 999px; height: 22px; margin-top: 12px; overflow: hidden; }\n  .progress-inner { background: var(--acc); height: 100%; border-radius: 999px; transition: width 0.5s ease; min-width: 0; }\n  .goal-edit { display: flex; align-items: center; gap: 8px; color: #fff; font-size: 13px; font-weight: 700; }\n  .goal-edit input { width: 70px; padding: 6px 8px; }\n  .stat-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 10px; }\n  .stat-tile { background: var(--ink); border-radius: 12px; padding: 14px 16px; }\n  .stat-tile:nth-child(even) { background: var(--acc); }\n  .stat-tile .label { font-size: 12px; color: #fff; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em; }\n  .stat-tile .value { font-size: 30px; font-weight: 900; color: var(--acc); margin-top: 4px; }\n  .stat-tile:nth-child(even) .label, .stat-tile:nth-child(even) .value { color: #000; }\n  .form-row { display: flex; gap: 10px; flex-wrap: wrap; align-items: end; margin-bottom: 10px; }\n  .field { display: flex; flex-direction: column; gap: 4px; font-size: 12px; font-weight: 700; min-width: 140px; flex: 1; }\n  input, select, textarea { font-family: inherit; padding: 10px 12px; border-radius: 10px; border: 2px solid var(--ink); background: #fff; color: var(--ink); font-size: 14px; font-weight: 500; }\n  input:focus, select:focus, textarea:focus, button:focus-visible { outline: 3px solid var(--acc); outline-offset: 1px; }\n  input::placeholder, textarea::placeholder { color: #8a8a8a; }\n  button { font-family: inherit; border: none; border-radius: 10px; padding: 10px 18px; font-weight: 800; font-size: 14px; cursor: pointer; }\n  button:active { transform: scale(0.96); }\n  .btn-primary { background: var(--acc); color: #000; }\n  .btn-ghost { background: var(--ink); color: var(--acc); }\n  .btn-del { background: #fff; color: var(--grey); border: 1.5px solid var(--line); padding: 5px 11px; font-size: 12px; }\n  .btn-small { padding: 6px 12px; font-size: 12px; }\n  .table-wrap { overflow-x: auto; }\n  table { width: 100%; border-collapse: collapse; font-size: 14px; }\n  th { text-align: left; padding: 9px 10px; font-weight: 800; border-bottom: 2px solid var(--ink); font-size: 12px; text-transform: uppercase; letter-spacing: 0.04em; white-space: nowrap; }\n  td { padding: 8px 10px; border-bottom: 1px solid var(--line); vertical-align: middle; }\n  td select, td input { padding: 7px 9px; font-size: 13px; }\n  tr.done-row { background: var(--acc-soft); }\n  tr.done-row td { font-weight: 700; }\n  tr.late td { background: #fff3e6; }\n  a.profile-link { color: var(--acc-dark); text-decoration: underline; font-weight: 800; font-size: 13px; }\n  .empty-note { color: var(--grey); font-size: 14px; font-style: italic; padding: 10px 0; }\n  .list-toolbar { display: flex; gap: 10px; align-items: center; margin-bottom: 10px; flex-wrap: wrap; }\n  .list-toolbar input[type=text] { flex: 1; min-width: 180px; }\n  .chips { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 12px; }\n  .chips button { background: #fff; color: #000; border: 2px solid #000; padding: 6px 12px; font-size: 13px; }\n  .chips button.on { background: var(--acc); border-color: var(--acc); }\n  .pager { display: flex; align-items: center; gap: 10px; margin-top: 10px; font-size: 13px; color: var(--grey); }\n  .pager button { padding: 6px 12px; font-size: 13px; }\n  .dm-card { border: 2px solid var(--ink); border-radius: 12px; padding: 16px; margin-bottom: 12px; background: #fff; }\n  .dm-title { font-weight: 900; font-size: 15px; color: var(--acc-dark); margin-bottom: 8px; }\n  .dm-body { font-size: 14px; color: #111; line-height: 1.55; margin-bottom: 10px; white-space: pre-wrap; }\n  .task-row { display: flex; align-items: center; gap: 10px; padding: 8px 10px; border-radius: 8px; margin-bottom: 5px; background: #f6f6f6; font-size: 14px; flex-wrap: wrap; }\n  .task-row .grow { flex: 1; min-width: 140px; font-weight: 700; }\n  .tag { font-size: 11px; font-weight: 800; color: var(--acc); background: var(--ink); padding: 4px 8px; border-radius: 999px; }\n  .bar { background: #eee; border-radius: 999px; height: 12px; overflow: hidden; margin: 4px 0 10px; }\n  .bar > div { background: var(--acc); height: 100%; }\n  .bar-row { display: flex; justify-content: space-between; font-size: 13px; font-weight: 700; }\n  .toast { position: fixed; top: 18px; right: 18px; background: var(--ink); border: 2px solid var(--acc); color: var(--acc); padding: 12px 20px; border-radius: 10px; font-weight: 800; font-size: 14px; opacity: 0; transform: translateY(-10px); transition: all 0.3s ease; pointer-events: none; z-index: 999; }\n  .toast.show { opacity: 1; transform: translateY(0); }\n  .small { font-size: 13px; color: var(--grey); }\n</style>\n</head>\n<body>\n<div class=\"app\">\n  <div class=\"brand\">\n    <img src=\"data:image/png;base64,\" alt=\"\">\n    <div>\n      <h1>Suits in Social Media CRM</h1>\n      <p class=\"subtitle\">Every new follower, every conversation, every firm. Social media for solicitors.</p>\n      <p class=\"small\" id=\"sync\" role=\"status\"></p>\n    </div>\n  </div>\n  <div class=\"divider\"></div>\n  <nav class=\"tabs\" id=\"tabNav\"></nav>\n  <div id=\"sections\"></div>\n</div>\n<div class=\"toast\" id=\"toast\" role=\"status\"></div>\n\n<script>\nvar K = { tab: \"suits_active_tab\", goal: \"suits_daily_goal\" };\nvar TABS = [[\"today\",\"Today\"],[\"dashboard\",\"Dashboard\"],[\"followers\",\"New followers\"],[\"pipeline\",\"Pipeline\"],[\"clients\",\"Firms\"],[\"scripts\",\"DM scripts\"],[\"wins\",\"Wins\"],[\"backup\",\"Backup\"]];\nvar FSTATUS = [\"New\",\"DM sent\",\"Replied\",\"Warm\",\"Profile check sent\",\"Call booked\",\"Won\",\"Not a fit\"];\nvar FFLAGS = [\"\",\"dm\",\"reply\",\"warm\",\"pcheck\",\"call\",\"won\"];\nvar AREAS = [\"\",\"Criminal\",\"Wills and probate\",\"Property\",\"Family\",\"Employment\",\"Other\"];\nvar PSTATUS = [\"New\",\"Contacted\",\"Interested\",\"Proposal sent\",\"Negotiating\",\"Won\",\"Lost\"];\nvar OFFERS = [\"Free profile check\",\"Sample month\",\"Month of posts\",\"3 months\",\"12 months\",\"Other\"];\nvar PER_PAGE = 50;\nvar fState = { page: 0, filter: \"All\" };\n\nfunction $(id) { return document.getElementById(id); }\nfunction esc(s) { return String(s == null ? \"\" : s).replace(/[&<>\"']/g, function (c) { return { \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\" }[c]; }); }\nfunction ls(k, f) { try { var v = JSON.parse(localStorage.getItem(k)); return v == null ? f : v; } catch (e) { return f; } }\nfunction setLs(k, v) { try { localStorage.setItem(k, JSON.stringify(v)); } catch (e) {} }\nfunction todayISO() { var d = new Date(), m = d.getMonth() + 1, day = d.getDate(); return d.getFullYear() + \"-\" + (m < 10 ? \"0\" : \"\") + m + \"-\" + (day < 10 ? \"0\" : \"\") + day; }\nfunction daysSince(iso) { if (!iso) return 0; return Math.round((Date.parse(todayISO()) - Date.parse(iso)) / 86400000); }\nfunction fmtGBP(n) { return \"\u00a3\" + Number(n || 0).toLocaleString(\"en-GB\"); }\nfunction showToast(msg) { var t = $(\"toast\"); t.textContent = msg; t.classList.add(\"show\"); setTimeout(function () { t.classList.remove(\"show\"); }, 2200); }\nfunction options(list, sel) { return list.map(function (o) { return '<option value=\"' + esc(o) + '\"' + (o === sel ? \" selected\" : \"\") + \">\" + esc(o || \"Choose\") + \"</option>\"; }).join(\"\"); }\nfunction copyText(btn, text) {\n  function done() { var o = btn.textContent; btn.textContent = \"Copied!\"; setTimeout(function () { btn.textContent = o; }, 1400); }\n  if (navigator.clipboard && navigator.clipboard.writeText) { navigator.clipboard.writeText(text).then(done, fallback); } else { fallback(); }\n  function fallback() { var ta = document.createElement(\"textarea\"); ta.value = text; document.body.appendChild(ta); ta.select(); try { document.execCommand(\"copy\"); done(); } catch (e) { showToast(\"Copy failed\"); } ta.remove(); }\n}\n\n/* ---------- data ---------- */\nvar S = { followers: [], pipeline: [], clients: [], wins: [] };\nvar SNAP = { followers: {}, pipeline: {}, clients: {}, wins: {} };\nvar KINDS = [\"followers\", \"pipeline\", \"clients\", \"wins\"];\nvar PW = window.SUITS_PW || \"\";\nvar BUSY = 0, ACTIVE = \"today\";\nfunction getF() { return S.followers; }\nfunction getP() { return S.pipeline; }\nfunction getC() { return S.clients; }\nfunction getW() { return S.wins; }\nfunction uid() { return Date.now().toString(36) + Math.random().toString(36).slice(2, 8); }\nfunction clean(x) { var c = {}; Object.keys(x).forEach(function (k) { if (k !== \"i\") c[k] = x[k]; }); return c; }\nfunction api(path, opts) {\n  opts = opts || {};\n  opts.headers = { \"Content-Type\": \"application/json\", \"x-suits-password\": PW };\n  return fetch(path, opts).then(function (r) { if (!r.ok) throw new Error(\"status \" + r.status); return r.json(); });\n}\nfunction setSync(state) {\n  var el = $(\"sync\"); if (!el) return;\n  var m = { ok: \"Shared list, saved for everyone\", saving: \"Saving...\", offline: \"Could not reach the shared list, retrying\", error: \"Last change did not save, please try again\" };\n  el.textContent = m[state] || \"\"; el.style.color = (state === \"ok\" || state === \"saving\") ? \"#6b6b6b\" : \"#b00020\";\n}\nfunction loadAll(cb) {\n  return api(\"/api/suits-crm/data\").then(function (d) {\n    KINDS.forEach(function (k) {\n      S[k] = (d[k] || []);\n      SNAP[k] = {};\n      S[k].forEach(function (x) { SNAP[k][x.id] = JSON.stringify(clean(x)); });\n    });\n    setSync(\"ok\"); if (cb) cb();\n  }).catch(function () { setSync(\"offline\"); });\n}\nfunction persist(kind, arr) {\n  S[kind] = arr;\n  var up = [], cur = {};\n  arr.forEach(function (x) {\n    if (!x.id) x.id = uid();\n    cur[x.id] = 1;\n    var j = JSON.stringify(clean(x));\n    if (SNAP[kind][x.id] !== j) { up.push({ id: x.id, data: clean(x) }); SNAP[kind][x.id] = j; }\n  });\n  var del = [];\n  Object.keys(SNAP[kind]).forEach(function (id) { if (!cur[id]) { del.push(id); delete SNAP[kind][id]; } });\n  if (!up.length && !del.length) return;\n  BUSY++; setSync(\"saving\");\n  api(\"/api/suits-crm/sync\", { method: \"POST\", body: JSON.stringify({ kind: kind, upserts: up, deletes: del }) })\n    .then(function () { setSync(\"ok\"); })\n    .catch(function () { setSync(\"error\"); showToast(\"That did not save. Check your connection.\"); })\n    .then(function () { BUSY--; });\n}\nfunction setStatus(f, s) {\n  f.status = s;\n  var r = FSTATUS.indexOf(s);\n  if (s === \"Not a fit\") return;\n  for (var i = 1; i <= r && i < FFLAGS.length; i++) { if (!f[FFLAGS[i]]) f[FFLAGS[i]] = todayISO(); }\n}\nfunction parseNames(txt) {\n  var out = [];\n  String(txt).split(/[\\s,;]+/).forEach(function (t) {\n    t = t.trim(); if (!t) return;\n    t = t.replace(/^https?:\\/\\/(www\\.)?instagram\\.com\\//i, \"\").replace(/[\\/?#].*$/, \"\").replace(/^@/, \"\");\n    if (/^[A-Za-z0-9._]{1,30}$/.test(t)) out.push(t);\n  });\n  return out;\n}\nfunction profileUrl(u) { return \"https://www.instagram.com/\" + encodeURIComponent(u) + \"/\"; }\n\n/* ---------- scripts ---------- */\nvar SCRIPTS = [\n  { t: \"1. Welcome to a new follower\", b: [\"Hi, thanks so much for the follow. I'm Vanessa. We're a little family business, me, my daughter and a friend, and we do social media for solicitors.\",\"I studied criminal law for two years, so I like a good legal brain. What area of law is your firm best known for?\"].join(\"\\n\\n\") },\n  { t: \"2. Gentle chat, after they reply\", b: [\"Lovely, that sounds really interesting. How long has the firm been going?\",\"I always wonder how solicitors find the time for any social media at all. Do you post yourselves, or does it fall to whoever has a spare ten minutes?\"].join(\"\\n\\n\") },\n  { t: \"3. Offer the free profile check\", b: [\"Can I be nosy? I'd love to have a proper look at your Instagram the way a new client would, and send you three little things to tweak. It's free, it takes me about ten minutes and there's no strings.\",\"If that sounds good, just reply BRIEF and I'll get on it.\"].join(\"\\n\\n\") },\n  { t: \"4. Profile check sent\", b: [\"I've had a good look at your profile and here are my three:\",\"1. [WIN ONE]\\n2. [WIN TWO]\\n3. [WIN THREE]\",\"Honestly there's a lot to like already. If any of it would help, I'm happy to talk it through. What do you think?\"].join(\"\\n\\n\") },\n  { t: \"5. Check in, three days later\", b: \"Hi again. I just wanted to check my message reached you. No rush at all, I know how full a solicitor's diary gets.\" },\n  { t: \"6. Second check in\", b: \"Last little nudge from me, I promise. A lot of the firms I chat to say the hardest part is knowing what they're allowed to post. That's the bit we take off your plate, and nothing ever goes out without you approving it first. Would you like to see what a month could look like for [FIRM]?\" },\n  { t: \"7. Worried about the rules\", b: \"That's a very fair worry, and with my law background it's one I take seriously. We never promise outcomes, we never use a client story without clear consent and you approve every single post. Shall I send you a sample month so you can see how it reads?\" },\n  { t: \"8. No time\", b: \"That's exactly why people ask us. You approve a batch when you have a spare minute and we handle the rest. Shall I show you what that looks like?\" },\n  { t: \"9. Asking about price\", b: \"Of course. Plans start at [PRICE] a month. How many posts a week do you think you'd like to be putting out?\" },\n  { t: \"10. Booking a call\", b: \"Lovely, I'd really enjoy a chat. I have [DAY] at [TIME] or [DAY] at [TIME]. Which suits you best?\" }\n];\n\n/* ---------- nav ---------- */\nfunction initNav() {\n  var nav = $(\"tabNav\"), secs = $(\"sections\");\n  TABS.forEach(function (t) {\n    var b = document.createElement(\"button\");\n    b.textContent = t[1]; b.id = \"navbtn-\" + t[0]; b.setAttribute(\"data-act\", \"tab\"); b.setAttribute(\"data-id\", t[0]);\n    nav.appendChild(b);\n    var s = document.createElement(\"div\"); s.className = \"tab-section\"; s.id = \"section-\" + t[0]; secs.appendChild(s);\n  });\n}\nfunction switchTab(id) {\n  TABS.forEach(function (t) {\n    $(\"navbtn-\" + t[0]).classList.toggle(\"active\", t[0] === id);\n    $(\"section-\" + t[0]).classList.toggle(\"active\", t[0] === id);\n  });\n  ACTIVE = id;\n  try { localStorage.setItem(K.tab, id); } catch (e) {}\n  if (id === \"today\") renderToday();\n  if (id === \"dashboard\") renderDashboard();\n  if (id === \"followers\") renderFollowers();\n  if (id === \"pipeline\") renderPipeline();\n  if (id === \"clients\") renderClients();\n  if (id === \"wins\") renderWins();\n}\n\n/* ---------- TODAY ---------- */\nfunction renderToday() {\n  var F = getF(), P = getP(), today = todayISO();\n  var goal = Number(ls(K.goal, 10)) || 10;\n  var sent = F.filter(function (f) { return f.dm === today; }).length;\n  var pct = Math.min(100, Math.round(sent / goal * 100));\n  var d = new Date().toLocaleDateString(\"en-GB\", { weekday: \"long\", day: \"numeric\", month: \"long\" });\n  var h = '<div class=\"card goal-card\"><div class=\"goal-top\"><h2>Today, ' + esc(d) + '</h2><div class=\"goal-edit\">Daily DM goal <input type=\"number\" min=\"1\" id=\"goalInput\" value=\"' + goal + '\" data-chg=\"goal\" aria-label=\"Daily DM goal\"></div></div>';\n  h += '<div class=\"goal-amount\">' + sent + ' of ' + goal + ' DMs sent</div><div class=\"progress-outer\"><div class=\"progress-inner\" style=\"width:' + pct + '%\"></div></div><div class=\"goal-sub\">Every new follower gets a welcome DM. Work down the list below.</div></div>';\n\n  var fresh = F.map(function (f, i) { f.i = i; return f; }).filter(function (f) { return f.status === \"New\"; }).slice(0, 15);\n  h += '<div class=\"card\"><h2>Say hello to these new followers</h2><p class=\"hint\">Oldest first. Copy the welcome DM, send it on Instagram, then tick it off.</p>';\n  if (!fresh.length) h += '<div class=\"empty-note\">Nobody waiting. Add new followers on the New followers tab.</div>';\n  fresh.forEach(function (f) {\n    h += '<div class=\"task-row\"><div class=\"grow\">@' + esc(f.u) + (f.area ? ' <span class=\"tag\">' + esc(f.area) + '</span>' : \"\") + '</div>' +\n      '<a class=\"profile-link\" href=\"' + profileUrl(f.u) + '\" target=\"_blank\" rel=\"noopener\">Open profile</a>' +\n      '<button class=\"btn-ghost btn-small\" data-act=\"copyDm\" data-n=\"0\">Copy welcome DM</button>' +\n      '<button class=\"btn-primary btn-small\" data-act=\"markDm\" data-i=\"' + f.i + '\">DM sent</button></div>';\n  });\n  h += '</div>';\n\n  var fu = [];\n  F.forEach(function (f, i) { if (f.status === \"DM sent\" && f.dm && daysSince(f.dm) >= 3) fu.push({ kind: \"Follower\", name: \"@\" + f.u, note: \"DM sent \" + daysSince(f.dm) + \" days ago\", url: profileUrl(f.u), i: i, scr: 4 }); });\n  P.forEach(function (p, i) { if (p.followup && p.followup <= today && p.status !== \"Won\" && p.status !== \"Lost\") fu.push({ kind: \"Pipeline\", name: p.firm, note: \"Follow up due \" + p.followup, i: i, scr: 5 }); });\n  h += '<div class=\"card\"><h2>Follow up today</h2><p class=\"hint\">Followers you messaged three or more days ago with no reply, and pipeline follow ups that are due.</p>';\n  if (!fu.length) h += '<div class=\"empty-note\">Nothing to chase. Lovely.</div>';\n  fu.forEach(function (x) {\n    h += '<div class=\"task-row\"><span class=\"tag\">' + x.kind + '</span><div class=\"grow\">' + esc(x.name) + ' <span class=\"small\">' + esc(x.note) + '</span></div>' +\n      (x.url ? '<a class=\"profile-link\" href=\"' + x.url + '\" target=\"_blank\" rel=\"noopener\">Open profile</a>' : \"\") +\n      '<button class=\"btn-ghost btn-small\" data-act=\"copyDm\" data-n=\"' + x.scr + '\">Copy follow up</button></div>';\n  });\n  h += '</div>';\n  $(\"section-today\").innerHTML = h;\n}\n\n/* ---------- DASHBOARD ---------- */\nfunction renderDashboard() {\n  var F = getF(), P = getP(), C = getC(), W = getW();\n  function cnt(flag) { return F.filter(function (f) { return f[flag]; }).length; }\n  var dm = cnt(\"dm\"), rep = cnt(\"reply\"), week = F.filter(function (f) { return daysSince(f.added) <= 7; }).length;\n  var mrr = C.reduce(function (a, c) { return a + (Number(c.fee) || 0); }, 0);\n  var open = P.filter(function (p) { return p.status !== \"Won\" && p.status !== \"Lost\"; }).length;\n  var tiles = [[\"Followers logged\", F.length], [\"Added in 7 days\", week], [\"DMs sent\", dm], [\"Replies\", rep], [\"Reply rate\", dm ? Math.round(rep / dm * 100) + \"%\" : \"0%\"], [\"Warm\", cnt(\"warm\")], [\"Profile checks sent\", cnt(\"pcheck\")], [\"Calls booked\", cnt(\"call\")], [\"Won from followers\", cnt(\"won\")], [\"Open pipeline\", open], [\"Firms\", C.length], [\"Monthly income\", fmtGBP(mrr)]];\n  var h = '<div class=\"card\"><h2>Live stats</h2><p class=\"hint\">Worked out from your followers, pipeline and firms.</p><div class=\"stat-grid\">';\n  tiles.forEach(function (t) { h += '<div class=\"stat-tile\"><div class=\"label\">' + t[0] + '</div><div class=\"value\">' + t[1] + '</div></div>'; });\n  h += '</div></div><div class=\"card\"><h2>Follower funnel</h2><p class=\"hint\">Where everyone is right now.</p>';\n  var max = Math.max(1, F.length);\n  FSTATUS.forEach(function (s) {\n    var n = F.filter(function (f) { return f.status === s; }).length;\n    h += '<div class=\"bar-row\"><span>' + esc(s) + '</span><span>' + n + '</span></div><div class=\"bar\"><div style=\"width:' + Math.round(n / max * 100) + '%\"></div></div>';\n  });\n  h += '</div><div class=\"card\"><h2>Pipeline</h2>';\n  PSTATUS.forEach(function (s) {\n    var n = P.filter(function (p) { return p.status === s; }).length;\n    h += '<div class=\"bar-row\"><span>' + esc(s) + '</span><span>' + n + '</span></div><div class=\"bar\"><div style=\"width:' + Math.round(n / Math.max(1, P.length) * 100) + '%\"></div></div>';\n  });\n  h += '<p class=\"small\">Wins logged: ' + W.length + '</p></div>';\n  $(\"section-dashboard\").innerHTML = h;\n}\n\n/* ---------- FOLLOWERS ---------- */\nfunction buildFollowers() {\n  $(\"section-followers\").innerHTML =\n    '<div class=\"card\"><h2>New followers</h2><p class=\"hint\">Paste each new follower, one per line, or paste a profile link. Duplicates are skipped.</p>' +\n    '<div class=\"form-row\"><div class=\"field\" style=\"flex:3\"><label for=\"f-new\">Usernames</label><textarea id=\"f-new\" rows=\"3\" placeholder=\"smithandco_solicitors&#10;@another_law_firm\"></textarea></div>' +\n    '<div class=\"field\"><label for=\"f-area\">Practice area</label><select id=\"f-area\">' + options(AREAS, \"\") + '</select></div>' +\n    '<button class=\"btn-primary\" data-act=\"addFollowers\">Add followers</button></div></div>' +\n    '<div class=\"card\"><div class=\"chips\" id=\"f-chips\"></div><div class=\"list-toolbar\"><input type=\"text\" id=\"f-search\" placeholder=\"Search username or notes...\" aria-label=\"Search followers\"></div>' +\n    '<div class=\"table-wrap\"><table><thead><tr><th>Username</th><th>Added</th><th>Area</th><th>Status</th><th>Notes</th><th></th></tr></thead><tbody id=\"f-tbody\"></tbody></table></div>' +\n    '<div class=\"empty-note\" id=\"f-empty\" style=\"display:none\">No followers here yet.</div>' +\n    '<div class=\"pager\"><button class=\"btn-ghost\" data-act=\"fPrev\">Prev</button><span id=\"f-page\"></span><button class=\"btn-ghost\" data-act=\"fNext\">Next</button></div></div>';\n  $(\"f-search\").oninput = function () { fState.page = 0; renderFollowers(); };\n}\nfunction renderFollowers() {\n  var F = getF().map(function (f, i) { f.i = i; return f; });\n  var chips = '';\n  [\"All\"].concat(FSTATUS).forEach(function (s) {\n    var n = s === \"All\" ? F.length : F.filter(function (f) { return f.status === s; }).length;\n    chips += '<button class=\"' + (fState.filter === s ? \"on\" : \"\") + '\" data-act=\"fFilter\" data-s=\"' + esc(s) + '\">' + esc(s) + ' (' + n + ')</button>';\n  });\n  $(\"f-chips\").innerHTML = chips;\n  var q = ($(\"f-search\").value || \"\").toLowerCase();\n  var list = F.filter(function (f) {\n    return (fState.filter === \"All\" || f.status === fState.filter) && (!q || f.u.toLowerCase().indexOf(q) > -1 || String(f.notes || \"\").toLowerCase().indexOf(q) > -1);\n  }).reverse();\n  var pages = Math.max(1, Math.ceil(list.length / PER_PAGE));\n  fState.page = Math.min(fState.page, pages - 1);\n  var slice = list.slice(fState.page * PER_PAGE, fState.page * PER_PAGE + PER_PAGE);\n  var h = \"\";\n  slice.forEach(function (f) {\n    h += '<tr class=\"' + (f.status === \"Won\" ? \"done-row\" : \"\") + '\"><td><a class=\"profile-link\" href=\"' + profileUrl(f.u) + '\" target=\"_blank\" rel=\"noopener\">@' + esc(f.u) + '</a></td>' +\n      '<td>' + esc(f.added || \"\") + '</td>' +\n      '<td><select data-chg=\"fArea\" data-i=\"' + f.i + '\" aria-label=\"Practice area for ' + esc(f.u) + '\">' + options(AREAS, f.area || \"\") + '</select></td>' +\n      '<td><select data-chg=\"fStatus\" data-i=\"' + f.i + '\" aria-label=\"Status for ' + esc(f.u) + '\">' + options(FSTATUS, f.status) + '</select></td>' +\n      '<td><input type=\"text\" data-chg=\"fNotes\" data-i=\"' + f.i + '\" value=\"' + esc(f.notes || \"\") + '\" placeholder=\"Notes\" aria-label=\"Notes for ' + esc(f.u) + '\"></td>' +\n      '<td style=\"white-space:nowrap\"><button class=\"btn-ghost btn-small\" data-act=\"copyDm\" data-n=\"0\">Copy DM</button> ' +\n      (f.inPipe ? '<span class=\"tag\">In pipeline</span>' : '<button class=\"btn-primary btn-small\" data-act=\"toPipe\" data-i=\"' + f.i + '\">To pipeline</button>') +\n      ' <button class=\"btn-del\" data-act=\"delF\" data-i=\"' + f.i + '\">remove</button></td></tr>';\n  });\n  $(\"f-tbody\").innerHTML = h;\n  $(\"f-empty\").style.display = list.length ? \"none\" : \"block\";\n  $(\"f-page\").textContent = \"Page \" + (fState.page + 1) + \" of \" + pages + \", \" + list.length + \" results\";\n}\n\n/* ---------- PIPELINE ---------- */\nfunction buildPipeline() {\n  $(\"section-pipeline\").innerHTML =\n    '<div class=\"card\"><h2>Pipeline: law firms in conversation</h2><p class=\"hint\">Log a firm the moment you start talking. Update the status as it moves.</p>' +\n    '<div class=\"form-row\"><div class=\"field\"><label for=\"pl-firm\">Firm name</label><input type=\"text\" id=\"pl-firm\"></div>' +\n    '<div class=\"field\"><label for=\"pl-contact\">Contact name</label><input type=\"text\" id=\"pl-contact\"></div>' +\n    '<div class=\"field\"><label for=\"pl-area\">Practice area</label><select id=\"pl-area\">' + options(AREAS, \"\") + '</select></div>' +\n    '<div class=\"field\"><label for=\"pl-offer\">Offer sent</label><select id=\"pl-offer\">' + options(OFFERS, \"\") + '</select></div></div>' +\n    '<div class=\"form-row\"><div class=\"field\"><label for=\"pl-status\">Status</label><select id=\"pl-status\">' + options(PSTATUS, \"New\") + '</select></div>' +\n    '<div class=\"field\"><label for=\"pl-follow\">Next follow up</label><input type=\"date\" id=\"pl-follow\"></div>' +\n    '<div class=\"field\" style=\"flex:2\"><label for=\"pl-notes\">Notes</label><input type=\"text\" id=\"pl-notes\"></div>' +\n    '<button class=\"btn-primary\" data-act=\"addLead\">Add firm</button></div></div>' +\n    '<div class=\"card\"><div class=\"list-toolbar\"><input type=\"text\" id=\"pl-search\" placeholder=\"Search firm...\" aria-label=\"Search pipeline\"></div>' +\n    '<div class=\"table-wrap\"><table><thead><tr><th>Firm</th><th>Contact</th><th>Area</th><th>Offer</th><th>Status</th><th>Follow up</th><th>Notes</th><th></th></tr></thead><tbody id=\"pl-tbody\"></tbody></table></div>' +\n    '<div class=\"empty-note\" id=\"pl-empty\" style=\"display:none\">No firms logged yet.</div></div>';\n  $(\"pl-search\").oninput = renderPipeline;\n}\nfunction renderPipeline() {\n  var P = getP().map(function (p, i) { p.i = i; return p; }), q = ($(\"pl-search\").value || \"\").toLowerCase(), today = todayISO();\n  var list = P.filter(function (p) { return !q || p.firm.toLowerCase().indexOf(q) > -1; }).reverse(), h = \"\";\n  list.forEach(function (p) {\n    var late = p.followup && p.followup < today && p.status !== \"Won\" && p.status !== \"Lost\";\n    h += '<tr class=\"' + (p.status === \"Won\" ? \"done-row\" : late ? \"late\" : \"\") + '\"><td>' + esc(p.firm) + '</td><td>' + esc(p.contact || \"\") + '</td><td>' + esc(p.area || \"\") + '</td><td>' + esc(p.offer || \"\") + '</td>' +\n      '<td><select data-chg=\"pStatus\" data-i=\"' + p.i + '\" aria-label=\"Status for ' + esc(p.firm) + '\">' + options(PSTATUS, p.status) + '</select></td>' +\n      '<td><input type=\"date\" data-chg=\"pFollow\" data-i=\"' + p.i + '\" value=\"' + esc(p.followup || \"\") + '\" aria-label=\"Follow up date for ' + esc(p.firm) + '\"></td>' +\n      '<td>' + esc(p.notes || \"\") + '</td><td><button class=\"btn-del\" data-act=\"delP\" data-i=\"' + p.i + '\">remove</button></td></tr>';\n  });\n  $(\"pl-tbody\").innerHTML = h;\n  $(\"pl-empty\").style.display = P.length ? \"none\" : \"block\";\n}\n\n/* ---------- CLIENTS ---------- */\nfunction buildClients() {\n  $(\"section-clients\").innerHTML =\n    '<div class=\"card\"><h2>Firms you work with</h2><p class=\"hint\">Your live roster and what each one pays you a month.</p>' +\n    '<div class=\"form-row\"><div class=\"field\"><label for=\"cl-firm\">Firm name</label><input type=\"text\" id=\"cl-firm\"></div>' +\n    '<div class=\"field\"><label for=\"cl-contact\">Contact name</label><input type=\"text\" id=\"cl-contact\"></div>' +\n    '<div class=\"field\"><label for=\"cl-area\">Practice area</label><select id=\"cl-area\">' + options(AREAS, \"\") + '</select></div>' +\n    '<div class=\"field\"><label for=\"cl-fee\">Monthly fee (\u00a3)</label><input type=\"number\" min=\"0\" id=\"cl-fee\"></div>' +\n    '<div class=\"field\"><label for=\"cl-start\">Start date</label><input type=\"date\" id=\"cl-start\"></div></div>' +\n    '<div class=\"form-row\"><div class=\"field\" style=\"flex:3\"><label for=\"cl-notes\">Notes</label><input type=\"text\" id=\"cl-notes\"></div><button class=\"btn-primary\" data-act=\"addClient\">Add firm</button></div>' +\n    '<div class=\"table-wrap\"><table><thead><tr><th>Firm</th><th>Contact</th><th>Area</th><th>Monthly</th><th>Started</th><th>Notes</th><th></th></tr></thead><tbody id=\"cl-tbody\"></tbody></table></div>' +\n    '<div class=\"empty-note\" id=\"cl-empty\" style=\"display:none\">No firms yet. Your first one is coming.</div><p class=\"small\" id=\"cl-total\"></p></div>';\n}\nfunction renderClients() {\n  var C = getC(), h = \"\", total = 0;\n  C.forEach(function (c, i) {\n    total += Number(c.fee) || 0;\n    h += '<tr><td>' + esc(c.firm) + '</td><td>' + esc(c.contact || \"\") + '</td><td>' + esc(c.area || \"\") + '</td><td>' + fmtGBP(c.fee) + '</td><td>' + esc(c.start || \"\") + '</td><td>' + esc(c.notes || \"\") + '</td><td><button class=\"btn-del\" data-act=\"delC\" data-i=\"' + i + '\">remove</button></td></tr>';\n  });\n  $(\"cl-tbody\").innerHTML = h;\n  $(\"cl-empty\").style.display = C.length ? \"none\" : \"block\";\n  $(\"cl-total\").textContent = C.length ? \"Monthly income from firms: \" + fmtGBP(total) : \"\";\n}\n\n/* ---------- SCRIPTS ---------- */\nfunction renderScripts() {\n  var h = '<div class=\"card\"><h2>Your DM scripts</h2><p class=\"hint\">Copy, swap the [BRACKETS] and send. Written in your voice for solicitors.</p>';\n  SCRIPTS.forEach(function (s, i) {\n    h += '<div class=\"dm-card\"><div class=\"dm-title\">' + esc(s.t) + '</div><div class=\"dm-body\">' + esc(s.b) + '</div><button class=\"btn-primary btn-small\" data-act=\"copyDm\" data-n=\"' + i + '\">Copy</button></div>';\n  });\n  $(\"section-scripts\").innerHTML = h + '</div>';\n}\n\n/* ---------- WINS ---------- */\nfunction buildWins() {\n  $(\"section-wins\").innerHTML = '<div class=\"card\"><h2>Log a win</h2><p class=\"hint\">First reply, first call, first firm. Write it down.</p>' +\n    '<div class=\"form-row\"><div class=\"field\" style=\"flex:4\"><label for=\"w-text\">What happened?</label><input type=\"text\" id=\"w-text\"></div><button class=\"btn-primary\" data-act=\"addWin\">Log it</button></div>' +\n    '<div id=\"w-list\"></div></div>';\n}\nfunction renderWins() {\n  var W = getW(), h = \"\";\n  W.map(function (w, i) { return { w: w, i: i }; }).reverse().forEach(function (x) {\n    h += '<div class=\"task-row\"><span class=\"tag\">' + esc(x.w.date) + '</span><div class=\"grow\">' + esc(x.w.text) + '</div><button class=\"btn-del\" data-act=\"delW\" data-i=\"' + x.i + '\">remove</button></div>';\n  });\n  $(\"w-list\").innerHTML = h || '<div class=\"empty-note\">No wins logged yet.</div>';\n}\n\n/* ---------- BACKUP ---------- */\nfunction buildBackup() {\n  $(\"section-backup\").innerHTML = '<div class=\"card\"><h2>Backup</h2><p class=\"hint\">The list is shared, so everyone who signs in sees the same followers, pipeline and firms, and changes appear within about 20 seconds. Download a backup now and then for safekeeping.</p>' +\n    '<div class=\"form-row\"><button class=\"btn-primary\" data-act=\"exportAll\">Download full backup</button><button class=\"btn-ghost\" data-act=\"exportCsv\">Download followers as CSV</button></div>' +\n    '<h3>Restore a backup</h3><div class=\"form-row\"><div class=\"field\"><label for=\"b-file\">Backup file</label><input type=\"file\" id=\"b-file\" accept=\".json,application/json\" data-chg=\"restore\"></div></div></div>';\n}\nfunction download(name, text, type) {\n  var a = document.createElement(\"a\"); a.href = URL.createObjectURL(new Blob([text], { type: type })); a.download = name; document.body.appendChild(a); a.click(); a.remove();\n}\nfunction csvCell(v) { return '\"' + String(v == null ? \"\" : v).replace(/\"/g, '\"\"') + '\"'; }\n\n/* ---------- events ---------- */\ndocument.addEventListener(\"click\", function (e) {\n  var b = e.target.closest(\"[data-act]\"); if (!b) return;\n  var act = b.getAttribute(\"data-act\"), i = Number(b.getAttribute(\"data-i\")), F, P, C, W;\n  if (act === \"tab\") return switchTab(b.getAttribute(\"data-id\"));\n  if (act === \"copyDm\") return copyText(b, SCRIPTS[Number(b.getAttribute(\"data-n\"))].b);\n  if (act === \"addFollowers\") {\n    var names = parseNames($(\"f-new\").value), area = $(\"f-area\").value; F = getF();\n    var have = {}; F.forEach(function (f) { have[f.u.toLowerCase()] = 1; });\n    var added = 0, skipped = 0;\n    names.forEach(function (n) { if (have[n.toLowerCase()]) { skipped++; return; } have[n.toLowerCase()] = 1; F.push({ u: n, added: todayISO(), status: \"New\", area: area, notes: \"\" }); added++; });\n    persist(\"followers\", F); $(\"f-new\").value = \"\"; fState.page = 0; renderFollowers();\n    return showToast(added ? \"Added \" + added + (skipped ? \", skipped \" + skipped + \" already here\" : \"\") : (names.length ? \"Already on your list\" : \"No usernames found\"));\n  }\n  if (act === \"markDm\") { F = getF(); if (F[i]) { setStatus(F[i], \"DM sent\"); persist(\"followers\", F); renderToday(); showToast(\"DM logged\"); } return; }\n  if (act === \"fFilter\") { fState.filter = b.getAttribute(\"data-s\"); fState.page = 0; return renderFollowers(); }\n  if (act === \"fPrev\") { fState.page = Math.max(0, fState.page - 1); return renderFollowers(); }\n  if (act === \"fNext\") { fState.page += 1; return renderFollowers(); }\n  if (act === \"delF\") { F = getF(); F.splice(i, 1); persist(\"followers\", F); return renderFollowers(); }\n  if (act === \"toPipe\") {\n    F = getF(); P = getP(); var f = F[i]; if (!f) return;\n    P.push({ firm: \"@\" + f.u, contact: \"\", area: f.area || \"\", offer: \"Free profile check\", status: \"Contacted\", followup: \"\", notes: \"From new followers\", date: todayISO() });\n    f.inPipe = true; persist(\"pipeline\", P); persist(\"followers\", F); renderFollowers(); return showToast(\"Added to pipeline\");\n  }\n  if (act === \"addLead\") {\n    var firm = $(\"pl-firm\").value.trim(); if (!firm) return showToast(\"Add a firm name first\");\n    P = getP(); P.push({ firm: firm, contact: $(\"pl-contact\").value.trim(), area: $(\"pl-area\").value, offer: $(\"pl-offer\").value, status: $(\"pl-status\").value, followup: $(\"pl-follow\").value, notes: $(\"pl-notes\").value.trim(), date: todayISO() });\n    persist(\"pipeline\", P); [\"pl-firm\", \"pl-contact\", \"pl-notes\", \"pl-follow\"].forEach(function (id) { $(id).value = \"\"; }); renderPipeline(); return showToast(\"Firm added\");\n  }\n  if (act === \"delP\") { P = getP(); P.splice(i, 1); persist(\"pipeline\", P); return renderPipeline(); }\n  if (act === \"addClient\") {\n    var cf = $(\"cl-firm\").value.trim(); if (!cf) return showToast(\"Add a firm name first\");\n    C = getC(); C.push({ firm: cf, contact: $(\"cl-contact\").value.trim(), area: $(\"cl-area\").value, fee: $(\"cl-fee\").value, start: $(\"cl-start\").value, notes: $(\"cl-notes\").value.trim() });\n    persist(\"clients\", C); [\"cl-firm\", \"cl-contact\", \"cl-fee\", \"cl-start\", \"cl-notes\"].forEach(function (id) { $(id).value = \"\"; }); renderClients(); return showToast(\"Firm added\");\n  }\n  if (act === \"delC\") { C = getC(); C.splice(i, 1); persist(\"clients\", C); return renderClients(); }\n  if (act === \"addWin\") {\n    var wt = $(\"w-text\").value.trim(); if (!wt) return showToast(\"Write the win first\");\n    W = getW(); W.push({ text: wt, date: todayISO() }); persist(\"wins\", W); $(\"w-text\").value = \"\"; renderWins(); return showToast(\"Win logged\");\n  }\n  if (act === \"delW\") { W = getW(); W.splice(i, 1); persist(\"wins\", W); return renderWins(); }\n  if (act === \"exportAll\") {\n    var all = {}; KINDS.forEach(function (k) { all[k] = S[k].map(clean); });\n    return download(\"suits-crm-backup-\" + todayISO() + \".json\", JSON.stringify(all, null, 1), \"application/json\");\n  }\n  if (act === \"exportCsv\") {\n    var rows = [[\"Username\", \"Added\", \"Area\", \"Status\", \"DM sent\", \"Replied\", \"Notes\"].map(csvCell).join(\",\")];\n    getF().forEach(function (f) { rows.push([f.u, f.added, f.area, f.status, f.dm, f.reply, f.notes].map(csvCell).join(\",\")); });\n    return download(\"suits-followers-\" + todayISO() + \".csv\", rows.join(\"\\n\"), \"text/csv\");\n  }\n});\ndocument.addEventListener(\"change\", function (e) {\n  var el = e.target, c = el.getAttribute && el.getAttribute(\"data-chg\"); if (!c) return;\n  var i = Number(el.getAttribute(\"data-i\")), F, P;\n  if (c === \"goal\") { setLs(K.goal, Math.max(1, Number(el.value) || 10)); return renderToday(); }\n  if (c === \"fStatus\") { F = getF(); if (F[i]) { setStatus(F[i], el.value); persist(\"followers\", F); renderFollowers(); showToast(\"Updated\"); } return; }\n  if (c === \"fArea\") { F = getF(); if (F[i]) { F[i].area = el.value; persist(\"followers\", F); } return; }\n  if (c === \"fNotes\") { F = getF(); if (F[i]) { F[i].notes = el.value; persist(\"followers\", F); } return; }\n  if (c === \"pStatus\") { P = getP(); if (P[i]) { P[i].status = el.value; persist(\"pipeline\", P); renderPipeline(); showToast(\"Updated\"); } return; }\n  if (c === \"pFollow\") { P = getP(); if (P[i]) { P[i].followup = el.value; persist(\"pipeline\", P); renderPipeline(); } return; }\n  if (c === \"restore\") {\n    var file = el.files && el.files[0]; if (!file) return;\n    var r = new FileReader();\n    r.onload = function () {\n      try {\n        var d = JSON.parse(r.result), n = 0;\n        KINDS.forEach(function (k) { if (Array.isArray(d[k])) { var have = {}; S[k].forEach(function (x) { have[x.id] = 1; }); d[k].forEach(function (x) { if (!x.id || have[x.id]) x.id = uid(); S[k].push(x); }); persist(k, S[k]); n++; } });\n        showToast(\"Restored \" + n + \" lists\"); switchTab(\"dashboard\");\n      } catch (err) { showToast(\"That file could not be read\"); }\n    };\n    r.readAsText(file);\n  }\n});\n\n/* ---------- start ---------- */\ninitNav(); buildFollowers(); buildPipeline(); buildClients(); buildWins(); buildBackup(); renderScripts();\nvar startTab = \"today\"; try { startTab = localStorage.getItem(K.tab) || \"today\"; } catch (e) {}\nif (!document.getElementById(\"section-\" + startTab)) startTab = \"today\";\nsetSync(\"saving\");\nloadAll(function () { switchTab(startTab); });\nfunction editing() { var a = document.activeElement; return a && /^(INPUT|TEXTAREA|SELECT)$/.test(a.tagName); }\nfunction refresh() {\n  if (BUSY > 0 || editing() || document.hidden) return;\n  loadAll(function () { if (ACTIVE !== \"backup\") switchTab(ACTIVE); });\n}\nsetInterval(refresh, 20000);\ndocument.addEventListener(\"visibilitychange\", function () { if (!document.hidden) refresh(); });\n</script>\n</body>\n</html>\n";
